SELECT AVG(icustays.los) AS average_los FROM admissions JOIN patients ON admissions.subject_id = patients.subject_id JOIN icustays ON admissions.stay_id = icustays.stay_id WHERE patients.gender = 'F' AND admissions.admission_type = 'sepsis' AND EXTRACT(YEAR FROM admissions.admittime) BETWEEN 2015 AND 2016 AND EXTRACT(YEAR FROM patients.anchor_year) BETWEEN 2015 AND 2016 AND (icustays.intime - admissions.admittime) > 0;